db()->exec("CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$defaults=['color_primary'=>'#bd8298','color_soft'=>'#e9b8c8','color_background'=>'#fffdfc','color_cream'=>'#f7f0e9','announcement'=>'Onde o carinho ganha forma em porcelana e 3D ✦'];
