if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$vals=[];foreach($defaults as $key=>$default){$v=trim((string)($_POST[$key]??$default));if(str_starts_with($key,'color_')&&!preg_match('/^#[0-9a-fA-F]{6}$/',$v))throw new RuntimeException('Use uma cor hexadecimal válida, como #E9B8C8.');$vals[$key]=$v;} $q=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($vals as $k=>$v)$q->execute([$k,$v]);flash('Identidade visual atualizada. Confira a vitrine.');}catch(Throwable $e){flash($e->getMessage(),'error');}header('Location: appearance.php');exit;}
$values=[];foreach($defaults as $k=>$v)$values[$k]=setting($k,$v);
admin_header('Identidade visual','appearance');?>
